import{_ as t,o as i,c as a,a0 as e}from"./chunks/framework.DQOulFGV.js";const l="/assets/01-data-model-chapter-01-overview.D5A1505s.svg",c=JSON.parse('{"title":"第1章 Redis 概览与定位","description":"","frontmatter":{},"headers":[],"relativePath":"redis/01-data-model/chapter-01-overview.md","filePath":"redis/01-data-model/chapter-01-overview.md"}'),n={name:"redis/01-data-model/chapter-01-overview.md"};function h(d,s,p,k,r,g){return i(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="第1章-redis-概览与定位" tabindex="-1">第1章 Redis 概览与定位 <a class="header-anchor" href="#第1章-redis-概览与定位" aria-label="Permalink to &quot;第1章 Redis 概览与定位&quot;">​</a></h1><blockquote><p>Redis 是一个基于内存的数据结构服务器。理解它的定位，是正确使用它的前提——先看清它是什么、擅长什么、不该用来做什么，再进入细节。</p></blockquote><hr><h2 id="_1-1-什么是-redis" tabindex="-1">1.1 什么是 Redis <a class="header-anchor" href="#_1-1-什么是-redis" aria-label="Permalink to &quot;1.1 什么是 Redis&quot;">​</a></h2><p>Redis（Remote Dictionary Server）是一个开源的键值对存储系统，数据保存在内存中，读写速度远超基于磁盘的数据库。它的本质是一个<strong>数据结构服务器</strong>：value 不只是普通字符串，而可以是 String、Hash、List、Set、ZSet 等多种数据结构，并针对每种结构提供原子操作命令。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>key  →  value（value 可以是多种数据结构）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;user:123&quot;        →  &quot;{name:&#39;张三&#39;, age:25}&quot;     String</span></span>
<span class="line"><span>&quot;user:123:info&quot;   →  {name, age, email}          Hash</span></span>
<span class="line"><span>&quot;news:list&quot;       →  [文章3, 文章2, 文章1]         List</span></span>
<span class="line"><span>&quot;user:123:tags&quot;   →  {Java, 后端, 分布式}          Set</span></span>
<span class="line"><span>&quot;leaderboard&quot;     →  {张三:100, 李四:200}          ZSet</span></span></code></pre></div><p>Redis 官方对它的定位是「内存数据结构服务器」，广泛用作缓存、消息队列、分布式锁、排行榜等。它常被放在 MySQL 这类持久化数据库之前，利用内存的高速访问缓解数据库压力。</p><h2 id="_1-2-核心特性" tabindex="-1">1.2 核心特性 <a class="header-anchor" href="#_1-2-核心特性" aria-label="Permalink to &quot;1.2 核心特性&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">特性</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">快</td><td style="text-align:left;">纯内存操作，单机 QPS 轻松突破 10 万</td></tr><tr><td style="text-align:left;">数据结构丰富</td><td style="text-align:left;">5 种基础类型 + 4 种高级类型，覆盖绝大多数业务场景</td></tr><tr><td style="text-align:left;">原子操作</td><td style="text-align:left;">命令由单线程执行，单条命令天然原子，无并发竞争</td></tr><tr><td style="text-align:left;">持久化</td><td style="text-align:left;">提供 RDB 快照与 AOF 日志两种持久化方式</td></tr><tr><td style="text-align:left;">高可用</td><td style="text-align:left;">主从复制、哨兵、集群三种方案逐级演进</td></tr><tr><td style="text-align:left;">功能扩展</td><td style="text-align:left;">支持事务、Lua 脚本、发布订阅、Pipeline 等</td></tr></tbody></table><h2 id="_1-3-版本演进" tabindex="-1">1.3 版本演进 <a class="header-anchor" href="#_1-3-版本演进" aria-label="Permalink to &quot;1.3 版本演进&quot;">​</a></h2><p><img src="`+l+`" alt="Redis 版本发展时间轴"></p><p>本书聚焦 <strong>Redis 6.0 ~ 7.2</strong>。6.0 起支持多线程网络 IO（命令执行仍单线程），7.0 引入 Functions 和 MP-AOF，7.2 彻底用 listpack 替代 ziplist。自 7.4 起 Redis 切换为 RSALv2 + SSPLv1 双协议，社区出现 Valkey 等开源分支。</p><h2 id="_1-4-适用场景与反模式" tabindex="-1">1.4 适用场景与反模式 <a class="header-anchor" href="#_1-4-适用场景与反模式" aria-label="Permalink to &quot;1.4 适用场景与反模式&quot;">​</a></h2><p><strong>适合的场景</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">缓存</td><td style="text-align:left;">热点数据缓存，缓解数据库压力</td></tr><tr><td style="text-align:left;">排行榜</td><td style="text-align:left;">ZSet 按 score 排序，天然适配</td></tr><tr><td style="text-align:left;">计数器</td><td style="text-align:left;">INCR 原子自增，无并发问题</td></tr><tr><td style="text-align:left;">分布式锁</td><td style="text-align:left;">SET NX PX 原子加锁</td></tr><tr><td style="text-align:left;">消息队列</td><td style="text-align:left;">List 阻塞弹出、Stream 消费者组</td></tr><tr><td style="text-align:left;">会话存储</td><td style="text-align:left;">共享 Session，TTL 自动过期</td></tr></tbody></table><p><strong>反模式</strong>（不该把 Redis 当作）：</p><table tabindex="0"><thead><tr><th style="text-align:left;">反模式</th><th style="text-align:left;">原因</th></tr></thead><tbody><tr><td style="text-align:left;">主数据库</td><td style="text-align:left;">内存容量有限，数据量大时成本高</td></tr><tr><td style="text-align:left;">强一致存储</td><td style="text-align:left;">主从复制异步，可能丢少量数据</td></tr><tr><td style="text-align:left;">大文件存储</td><td style="text-align:left;">大 Key 阻塞命令执行、占用带宽</td></tr><tr><td style="text-align:left;">关系型查询</td><td style="text-align:left;">无 SQL、无复杂关联查询能力</td></tr></tbody></table><h2 id="_1-5-与-memcached-对比" tabindex="-1">1.5 与 Memcached 对比 <a class="header-anchor" href="#_1-5-与-memcached-对比" aria-label="Permalink to &quot;1.5 与 Memcached 对比&quot;">​</a></h2><p>Memcached 是另一款常见的内存缓存，二者常被放在一起比较：</p><table tabindex="0"><thead><tr><th style="text-align:left;">对比项</th><th style="text-align:left;">Redis</th><th style="text-align:left;">Memcached</th></tr></thead><tbody><tr><td style="text-align:left;">数据类型</td><td style="text-align:left;">5 种基础 + 4 种高级</td><td style="text-align:left;">仅 String</td></tr><tr><td style="text-align:left;">持久化</td><td style="text-align:left;">支持 RDB/AOF</td><td style="text-align:left;">不支持</td></tr><tr><td style="text-align:left;">集群</td><td style="text-align:left;">原生支持主从/哨兵/集群</td><td style="text-align:left;">需客户端实现分片</td></tr><tr><td style="text-align:left;">线程模型</td><td style="text-align:left;">单线程 + IO 多路复用</td><td style="text-align:left;">多线程</td></tr><tr><td style="text-align:left;">功能</td><td style="text-align:left;">事务、Lua、订阅、Pipeline</td><td style="text-align:left;">无</td></tr></tbody></table><p>选择标准：需要丰富数据结构、持久化、高可用时选 Redis；仅做简单 KV 缓存、追求极致简洁时 Memcached 才进入考虑范围。</p><hr><h2 id="_1-6-快速上手-启动-redis-与第一个命令" tabindex="-1">1.6 快速上手：启动 Redis 与第一个命令 <a class="header-anchor" href="#_1-6-快速上手-启动-redis-与第一个命令" aria-label="Permalink to &quot;1.6 快速上手：启动 Redis 与第一个命令&quot;">​</a></h2><p>读十遍不如敲一遍。本节用 Docker 一键拉起 Redis，并完成从连接到关闭的完整流程。后续每章的「实操演示」都基于这个环境。</p><h3 id="环境准备" tabindex="-1">环境准备 <a class="header-anchor" href="#环境准备" aria-label="Permalink to &quot;环境准备&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 拉取镜像并启动一个 Redis 7 容器（端口 6379）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis-demo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 6379:6379</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis:7</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 进入容器内部的 redis-cli</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis-demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis-cli</span></span></code></pre></div><p>进入后，先确认服务活着：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">127.0.0.1:6379</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PING</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PONG</span></span></code></pre></div><p><code>PONG</code> 就是 Redis 的「我在」。</p><h3 id="第一个键值" tabindex="-1">第一个键值 <a class="header-anchor" href="#第一个键值" aria-label="Permalink to &quot;第一个键值&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">127.0.0.1:6379</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">OK</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">127.0.0.1:6379</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;redis&quot;</span></span></code></pre></div><p><code>OK</code> 是命令执行成功的标志，<code>&quot;redis&quot;</code> 是取回的值。再看两个常用命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">127.0.0.1:6379</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EXISTS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 判断 key 是否存在</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">integer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">127.0.0.1:6379</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">TTL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # 查看剩余生存时间（秒）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">integer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">-1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # -1 = 永久有效，-2 = 已不存在</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">127.0.0.1:6379</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EXPIRE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 设置 60 秒过期</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">integer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">127.0.0.1:6379</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">TTL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">integer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">60</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # 开始倒计时</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">127.0.0.1:6379</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # 删除 key</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">integer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">1</span></span></code></pre></div><h3 id="关闭与清理" tabindex="-1">关闭与清理 <a class="header-anchor" href="#关闭与清理" aria-label="Permalink to &quot;关闭与清理&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">127.0.0.1:6379</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">QUIT</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 退出 redis-cli</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis-demo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis-demo</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 停止并移除容器</span></span></code></pre></div><blockquote><p>掌握 <code>SET / GET / DEL / EXISTS / TTL / EXPIRE</code> 这六个命令，你已经能完成「缓存 + 过期」这一 Redis 最核心的使用场景。其余数据类型只是 value 的形态不同，操作心智完全一致。</p></blockquote><h3 id="本地无-docker-怎么办" tabindex="-1">本地无 Docker 怎么办 <a class="header-anchor" href="#本地无-docker-怎么办" aria-label="Permalink to &quot;本地无 Docker 怎么办&quot;">​</a></h3><p>没有 Docker 也可以用官方源安装 Redis，或用 Docker 之外的容器运行时。核心是拿到一个可交互的 <code>redis-cli</code>，本文所有命令都在 <code>redis-cli</code> 中执行。</p>`,39)])])}const y=t(n,[["render",h]]);export{c as __pageData,y as default};
